@namespace sv_03324c3c91544d04a483d904996fe386.Components.Pages.Settings

<nav class="settings-sidebar">
    <h5 class="sidebar-title">Settings</h5>
    <ul class="nav-list">
        @foreach (var section in Sections)
        {
            <li class="nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
    min-height: 100%;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.nav-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    color: #495057;
    transition: background-color 0.15s, color 0.15s;
    border-left: 3px solid transparent;
    font-size: 0.95rem;
}

.nav-item:hover {
    background: #e9ecef;
    color: #212529;
}

.nav-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

@namespace sv_03324c3c91544d04a483d904996fe386.Components.Pages.Settings

<div class="change-password-panel">
    <button class="panel-toggle" @onclick="ToggleExpanded">
        <span>🔑 Change Password</span>
        <span class="toggle-icon">@(IsExpanded ? "▲" : "▼")</span>
    </button>

    @if (IsExpanded)
    {
        <div class="panel-body">
            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger">@errorMessage</div>
            }
            @if (!string.IsNullOrEmpty(successMessage))
            {
                <div class="alert alert-success">@successMessage</div>
            }

            <div class="form-group">
                <label>Current Password</label>
                <input type="password" class="form-control" @bind="currentPassword" />
            </div>
            <div class="form-group">
                <label>New Password</label>
                <input type="password" class="form-control" @bind="newPassword" />
            </div>
            <div class="form-group">
                <label>Confirm New Password</label>
                <input type="password" class="form-control" @bind="confirmPassword" />
            </div>
            <button class="btn btn-primary" @onclick="HandleSubmit" disabled="@isSaving">
                @(isSaving ? "Updating…" : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? errorMessage;
    private string? successMessage;
    private bool isSaving;

    private void ToggleExpanded() => IsExpanded = !IsExpanded;

    private async Task HandleSubmit()
    {
        errorMessage = null;
        successMessage = null;

        if (string.IsNullOrWhiteSpace(currentPassword))
        {
            errorMessage = "Current password is required.";
            return;
        }
        if (newPassword.Length < 8)
        {
            errorMessage = "New password must be at least 8 characters.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        isSaving = true;
        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        isSaving = false;

        successMessage = "Password updated successfully.";
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }
}

