arguments.file_text:
@using sv_03324c3c91544d04a483d904996fe386.Models
@namespace sv_03324c3c91544d04a483d904996fe386.Components.Pages.Settings

<section class="settings-section">
    <h3>Profile</h3>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert alert-success">@statusMessage</div>
    }

    <div class="profile-layout">
        <div class="avatar-area">
            <div class="avatar-preview">
                <img src="@editAvatarUrl" alt="Avatar" />
            </div>
            <span class="avatar-url-label">Avatar URL</span>
            <input type="text" class="form-control" value="@editAvatarUrl"
                   @oninput="e => editAvatarUrl = e.Value?.ToString() ?? string.Empty" />
        </div>

        <div class="profile-fields">
            <div class="form-group">
                <label>Display Name</label>
                <input type="text" class="form-control" @bind="editDisplayName" />
            </div>
            <div class="form-group">
                <label>Email</label>
                <input type="email" class="form-control" @bind="editEmail" />
            </div>
            <div class="form-group">
                <label>Bio</label>
                <textarea class="form-control" rows="4" @bind="editBio"></textarea>
            </div>
        </div>
    </div>

    <div class="action-buttons">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="DiscardChanges">
            Discard Changes
        </button>
    </div>
</section>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";
    private string? statusMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasInitialized)
        {
            CopyFromProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void CopyFromProfile()
    {
        if (Profile is null) return;
        editDisplayName = Profile.DisplayName;
        editEmail = Profile.Email;
        editAvatarUrl = Profile.AvatarUrl;
        editBio = Profile.Bio;
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        statusMessage = null;

        var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
        await OnSave.InvokeAsync(updated);

        statusMessage = "Profile saved successfully!";
        isSaving = false;
    }

    private void DiscardChanges()
    {
        CopyFromProfile();
        statusMessage = null;
    }
}

.settings-section h3 {
    margin: 0 0 1.5rem;
    font-size: 1.35rem;
    font-weight: 600;
    color: #212529;
}

.profile-layout {
    display: flex;
    gap: 2rem;
    margin-bottom: 1.5rem;
}

.avatar-area {
    flex: 0 0 180px;
    text-align: center;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    margin: 0 auto 0.75rem;
    border: 3px solid #dee2e6;
    background: #f8f9fa;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-url-label {
    display: block;
    font-size: 0.8rem;
    color: #6c757d;
    margin-bottom: 0.35rem;
}

.avatar-area .form-control {
    font-size: 0.8rem;
}

.profile-fields {
    flex: 1;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #495057;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.9rem;
}

textarea.form-control {
    resize: vertical;
}

.action-buttons {
    display: flex;
    gap: 0.75rem;
}

.alert {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.alert-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

@using sv_03324c3c91544d04a483d904996fe386.Models
@namespace sv_03324c3c91544d04a483d904996fe386.Components.Pages.Settings

<section class="settings-section">
    <h3>Notifications</h3>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert alert-success">@statusMessage</div>
    }

    <div class="toggle-group">
        <div class="toggle-row">
            <label class="toggle-label">
                <span>📧 Email Notifications</span>
                <span class="toggle-description">Receive email for important updates</span>
            </label>
            <label class="switch">
                <input type="checkbox" checked="@emailNotifications"
                       @onchange="e => emailNotifications = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </div>

        <div class="toggle-row">
            <label class="toggle-label">
                <span>📱 Push Notifications</span>
                <span class="toggle-description">Get real-time push alerts</span>
            </label>
            <label class="switch">
                <input type="checkbox" checked="@pushNotifications"
                       @onchange="e => pushNotifications = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </div>

        <div class="toggle-row">
            <label class="toggle-label">
                <span>📰 Weekly Digest</span>
                <span class="toggle-description">Receive a weekly summary email</span>
            </label>
            <label class="switch">
                <input type="checkbox" checked="@weeklyDigest"
                       @onchange="e => weeklyDigest = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </div>
    </div>

    <h4 class="subsection-title">Muted Channels</h4>
    <p class="subsection-description">Uncheck channels you want to receive notifications from.</p>

    <div class="channel-list">
        @foreach (var channel in channels)
        {
            <label class="channel-item">
                <input type="checkbox" checked="@channel.IsMuted"
                       @onchange="e => channel.IsMuted = (bool)(e.Value ?? false)" />
                <span class="channel-name"># @channel.Name</span>
            </label>
        }
    </div>

    <div class="action-buttons">
        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save Preferences")
        </button>
    </div>
</section>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<ChannelState> channels = [];
    private string? statusMessage;
    private bool isSaving;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            channels = Prefs.MutedChannels
                .Select(c => new ChannelState { Name = c, IsMuted = true })
                .ToList();
            hasInitialized = true;
        }
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        statusMessage = null;

        var mutedChannels = channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await OnSave.InvokeAsync(updated);

        statusMessage = "Notification preferences saved!";
        isSaving = false;
    }

    private class ChannelState
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }
}

.settings-section h3 {
    margin: 0 0 1.5rem;
    font-size: 1.35rem;
    font-weight: 600;
}

.toggle-group {
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    border: 1px solid #dee2e6;
