            </div>

            <div class="control-group">
                <div class="toggle-row">
                    <label class="toggle-label">
                        <span>Compact Mode</span>
                        <span class="toggle-description">Reduce spacing for denser content</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" checked="@compactMode"
                               @onchange="e => compactMode = (bool)(e.Value ?? false)" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>
        </div>

        <div class="preview-area">
            <h4 class="subsection-title">Live Preview</h4>
            <div class="preview-card @GetPreviewThemeClass()" style="@GetPreviewStyle()">
                <div class="preview-header">
                    <span class="preview-dot red"></span>
                    <span class="preview-dot yellow"></span>
                    <span class="preview-dot green"></span>
                    <span class="preview-title">Preview Window</span>
                </div>
                <div class="preview-body" style="@(compactMode ? "padding: 0.5rem;" : "padding: 1rem;")">
                    <h5 style="margin: 0 0 0.5rem;">Dashboard</h5>
                    <p style="margin: 0 0 @(compactMode ? "0.25rem" : "0.75rem");">
                        This is how your content will appear with the selected settings.
                    </p>
                    <div class="preview-items">
                        <div class="preview-item" style="@(compactMode ? "padding: 0.35rem 0.5rem;" : "padding: 0.5rem 0.75rem;")">
                            📊 Analytics
                        </div>
                        <div class="preview-item" style="@(compactMode ? "padding: 0.35rem 0.5rem;" : "padding: 0.5rem 0.75rem;")">
                            📋 Reports
                        </div>
                        <div class="preview-item" style="@(compactMode ? "padding: 0.35rem 0.5rem;" : "padding: 0.5rem 0.75rem;")">
                            ⚙️ Settings
                        </div>
                    </div>
                </div>
                <div class="preview-footer">
                    Theme: @selectedTheme · Font: @selectedFontSize · Lang: @selectedLanguage
                    @(compactMode ? " · Compact" : "")
                </div>
            </div>
        </div>
    </div>

    <div class="action-buttons">
        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save")
        </button>
