@code {
    [Parameter] public AppearanceSettings? Appearance { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private string? statusMessage;
    private bool isSaving;
    private bool hasInitialized;

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    protected override void OnParametersSet()
    {
        if (Appearance is not null && !hasInitialized)
        {
            selectedTheme = Appearance.Theme;
            selectedFontSize = Appearance.FontSize;
            selectedLanguage = Appearance.Language;
            compactMode = Appearance.CompactMode;
            hasInitialized = true;
        }
    }

    private async Task SaveAppearance()
    {
        isSaving = true;
        statusMessage = null;

        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);

        statusMessage = "Appearance settings saved!";
        isSaving = false;
    }

    private string GetPreviewThemeClass() => selectedTheme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string GetPreviewStyle()
    {
        var fontSize = selectedFontSize switch
        {
            "Small" => "0.8rem",
            "Large" => "1.1rem",
            _ => "0.95rem"
        };
        return $"font-size: {fontSize};";
    }
}

