@namespace sv_03324c3c91544d04a483d904996fe386.Components.Pages.Settings

<section class="settings-section">
    <h3>Security</h3>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="security-card">
        <div class="tfa-row">
            <div>
                <h4 class="subsection-title">Two-Factor Authentication</h4>
                <p class="subsection-description">
                    Add an extra layer of security to your account.
                </p>
            </div>
            <div class="tfa-status">
                <span class="status-badge @(twoFactorEnabled ? "enabled" : "disabled")">
                    @(twoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
                <label class="switch">
                    <input type="checkbox" checked="@twoFactorEnabled"
                           @onchange="Toggle2FA" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        @if (Security?.LastPasswordChange is not null)
        {
            <p class="last-changed">
                Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }
    </div>

    <h4 class="subsection-title">Active Sessions</h4>
    <p class="subsection-description">Manage devices where you're currently signed in.</p>

    <div class="sessions-table-wrapper">
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @if (Security is not null)
                {
                    @foreach (var session in Security.Sessions)
                    {
                        var isCurrent = session == Security.Sessions.First();
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>
    </div>

    <RevokeSessionDialog Session="sessionToRevoke"
                         IsVisible="showRevokeDialog"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="CancelRevoke" />
</section>

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool twoFactorEnabled;
    private ActiveSession? sessionToRevoke;
    private bool showRevokeDialog;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Security is not null && !hasInitialized)
        {
            twoFactorEnabled = Security.TwoFactorEnabled;
            hasInitialized = true;
        }
    }

    private void Toggle2FA(ChangeEventArgs e)
    {
        twoFactorEnabled = (bool)(e.Value ?? false);
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await OnChangePassword.InvokeAsync(args);
    }

    private void PromptRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
        }
        showRevokeDialog = false;
        sessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        showRevokeDialog = false;
        sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}
