<section class="settings-section">
    <h3>Appearance</h3>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert alert-success">@statusMessage</div>
    }

    <div class="appearance-grid">
        <div class="controls-area">
            <div class="control-group">
                <h4 class="subsection-title">Theme</h4>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-option">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(selectedTheme == theme)"
                               @onchange="() => selectedTheme = theme" />
                        <span class="radio-label">@theme</span>
                    </label>
                }
            </div>

            <div class="control-group">
                <h4 class="subsection-title">Font Size</h4>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-option">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(selectedFontSize == size)"
                               @onchange="() => selectedFontSize = size" />
                        <span class="radio-label">@size</span>
                    </label>
                }
            </div>

            <div class="control-group">
                <h4 class="subsection-title">Language</h4>
                <select class="form-control" value="@selectedLanguage"
                        @onchange="e => selectedLanguage = e.Value?.ToString() ?? "English"">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="control-group">
                <div class="toggle-row">
                    <label class="toggle-label">
                        <span>Compact Mode</span>
                        <span class="toggle-description">Reduce spacing for denser content</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" checked="@compactMode"
                               @onchange="e => compactMode = (bool)(e.Value ?? false)" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>
        </div>

        <div class="preview-area">
            <h4 class="subsection-title">Live Preview</h4>
            <div class="preview-card @GetPreviewThemeClass()" style="@GetPreviewStyle()">
                <div class="preview-header">
                    <span class="preview-dot red"></span>
                    <span class="preview-dot yellow"></span>
                    <span class="preview-dot green"></span>
                    <span class="preview-title">Preview Window</span>
                </div>
                <div class="preview-body" style="@(compactMode ? "padding: 0.5rem;" : "padding: 1rem;")">
                    <h5 style="margin: 0 0 0.5rem;">Dashboard</h5>
                    <p style="margin: 0 0 @(compactMode ? "0.25rem" : "0.75rem");">
                        This is how your content will appear with the selected settings.
                    </p>
                    <div class="preview-items">
                        <div class="preview-item" style="@(compactMode ? "padding: 0.35rem 0.5rem;" : "padding: 0.5rem 0.75rem;")">
                            📊 Analytics
                        </div>
                        <div class="preview-item" style="@(compactMode ? "padding: 0.35rem 0.5rem;" : "padding: 0.5rem 0.75rem;")">
                            📋 Reports
                        </div>
                        <div class="preview-item" style="@(compactMode ? "padding: 0.35rem 0.5rem;" : "padding: 0.5rem 0.75rem;")">
                            ⚙️ Settings
                        </div>
                    </div>
                </div>
                <div class="preview-footer">
                    Theme: @selectedTheme · Font: @selectedFontSize · Lang: @selectedLanguage
                    @(compactMode ? " · Compact" : "")
                </div>
            </div>
        </div>
    </div>

    <div class="action-buttons">
        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save")
        </button>
    </div>
</section>

@code {
    [Parameter] public AppearanceSettings? Appearance { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private string? statusMessage;
    private bool isSaving;
    private bool hasInitialized;

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    protected override void OnParametersSet()
    {
        if (Appearance is not null && !hasInitialized)
        {
            selectedTheme = Appearance.Theme;
            selectedFontSize = Appearance.FontSize;
            selectedLanguage = Appearance.Language;
            compactMode = Appearance.CompactMode;
            hasInitialized = true;
        }
    }

    private async Task SaveAppearance()
    {
        isSaving = true;
        statusMessage = null;

        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);

        statusMessage = "Appearance settings saved!";
        isSaving = false;
    }

    private string GetPreviewThemeClass() => selectedTheme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string GetPreviewStyle()
    {
        var fontSize = selectedFontSize switch
        {
            "Small" => "0.8rem",
            "Large" => "1.1rem",
            _ => "0.95rem"
        };
        return $"font-size: {fontSize};";
    }
}
