.settings-section h3 {
    margin: 0 0 1.5rem;
    font-size: 1.35rem;
    font-weight: 600;
    color: #212529;
}

.profile-layout {
    display: flex;
    gap: 2rem;
    margin-bottom: 1.5rem;
}

.avatar-area {
    flex: 0 0 180px;
    text-align: center;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    margin: 0 auto 0.75rem;
    border: 3px solid #dee2e6;
    background: #f8f9fa;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-url-label {
    display: block;
    font-size: 0.8rem;
    color: #6c757d;
    margin-bottom: 0.35rem;
}

.avatar-area .form-control {
    font-size: 0.8rem;
}

.profile-fields {
    flex: 1;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #495057;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.9rem;
}

textarea.form-control {
    resize: vertical;
}

.action-buttons {
    display: flex;
    gap: 0.75rem;
}

.alert {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.alert-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

