@using sv_03324c3c91544d04a483d904996fe386.Models
@namespace sv_03324c3c91544d04a483d904996fe386.Components.Pages.Settings

<section class="settings-section">
    <h3>Notifications</h3>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert alert-success">@statusMessage</div>
    }

    <div class="toggle-group">
        <div class="toggle-row">
            <label class="toggle-label">
                <span>📧 Email Notifications</span>
                <span class="toggle-description">Receive email for important updates</span>
            </label>
            <label class="switch">
                <input type="checkbox" checked="@emailNotifications"
                       @onchange="e => emailNotifications = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </div>

        <div class="toggle-row">
            <label class="toggle-label">
                <span>📱 Push Notifications</span>
                <span class="toggle-description">Get real-time push alerts</span>
            </label>
            <label class="switch">
                <input type="checkbox" checked="@pushNotifications"
                       @onchange="e => pushNotifications = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </div>

        <div class="toggle-row">
            <label class="toggle-label">
                <span>📰 Weekly Digest</span>
                <span class="toggle-description">Receive a weekly summary email</span>
            </label>
            <label class="switch">
                <input type="checkbox" checked="@weeklyDigest"
                       @onchange="e => weeklyDigest = (bool)(e.Value ?? false)" />
                <span class="slider"></span>
            </label>
        </div>
    </div>

    <h4 class="subsection-title">Muted Channels</h4>
    <p class="subsection-description">Uncheck channels you want to receive notifications from.</p>

    <div class="channel-list">
        @foreach (var channel in channels)
        {
            <label class="channel-item">
                <input type="checkbox" checked="@channel.IsMuted"
                       @onchange="e => channel.IsMuted = (bool)(e.Value ?? false)" />
                <span class="channel-name"># @channel.Name</span>
            </label>
        }
    </div>

    <div class="action-buttons">
        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save Preferences")
        </button>
    </div>
</section>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<ChannelState> channels = [];
    private string? statusMessage;
    private bool isSaving;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            channels = Prefs.MutedChannels
                .Select(c => new ChannelState { Name = c, IsMuted = true })
                .ToList();
            hasInitialized = true;
        }
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        statusMessage = null;

        var mutedChannels = channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await OnSave.InvokeAsync(updated);

        statusMessage = "Notification preferences saved!";
        isSaving = false;
    }

    private class ChannelState
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }
}

