toolArgs.file_text:
.settings-section h3 {
    margin: 0 0 1.5rem;
    font-size: 1.35rem;
    font-weight: 600;
}

.toggle-group {
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    margin-bottom: 0.75rem;
    background: #fff;
}

.toggle-label {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    cursor: pointer;
}

.toggle-label > span:first-child {
    font-weight: 500;
    font-size: 0.95rem;
}

.toggle-description {
    font-size: 0.8rem;
    color: #6c757d;
}

/* Toggle switch */
.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

input:checked + .slider {
    background-color: #0d6efd;
}

input:checked + .slider::before {
    transform: translateX(22px);
}

.subsection-title {
    font-size: 1rem;
    font-weight: 600;
    margin: 0 0 0.25rem;
    color: #212529;
}

.subsection-description {
    font-size: 0.85rem;
    color: #6c757d;
    margin: 0 0 0.75rem;
}

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item:hover {
    background: #f8f9fa;
}

.channel-name {
    color: #495057;
}

.action-buttons {
    display: flex;
    gap: 0.75rem;
}

.alert {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.alert-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

