toolArgs.file_text:
.settings-section h3 {
    margin: 0 0 1.5rem;
    font-size: 1.35rem;
    font-weight: 600;
}

.security-card {
    margin: 1.5rem 0;
    padding: 1.25rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    background: #fff;
}

.tfa-row {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1rem;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-shrink: 0;
}

.status-badge {
    padding: 0.25rem 0.6rem;
    border-radius: 1rem;
    font-size: 0.8rem;
    font-weight: 600;
}

.status-badge.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-badge.disabled {
    background: #f8d7da;
    color: #842029;
}

.subsection-title {
    font-size: 1rem;
    font-weight: 600;
    margin: 0 0 0.25rem;
}

.subsection-description {
    font-size: 0.85rem;
    color: #6c757d;
    margin: 0 0 0.75rem;
}

.last-changed {
    margin: 0.75rem 0 0;
    font-size: 0.85rem;
    color: #6c757d;
}

/* Toggle switch */
.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

input:checked + .slider {
    background-color: #0d6efd;
}

input:checked + .slider::before {
    transform: translateX(22px);
}

.sessions-table-wrapper {
    overflow-x: auto;
    margin-bottom: 1.5rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.75rem;
    border-bottom: 2px solid #dee2e6;
    font-weight: 600;
    color: #495057;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.sessions-table td {
    padding: 0.75rem;
    border-bottom: 1px solid #dee2e6;
    vertical-align: middle;
}

.sessions-table tbody tr:hover {
    background: #f8f9fa;
}

.current-badge {
    display: inline-block;
    margin-left: 0.5rem;
    padding: 0.15rem 0.5rem;
    border-radius: 1rem;
    font-size: 0.7rem;
    font-weight: 600;
    background: #cfe2ff;
    color: #084298;
}

.btn-sm {
    padding: 0.3rem 0.6rem;
    font-size: 0.8rem;
}

.btn-outline-danger {
    color: #dc3545;
    border: 1px solid #dc3545;
    background: transparent;
    border-radius: 0.375rem;
    cursor: pointer;
}

.btn-outline-danger:hover {
    background: #dc3545;
    color: #fff;
}

