arguments.file_text:
@page "/settings"
@using sv_03324c3c91544d04a483d904996fe386.Models
@namespace sv_03324c3c91544d04a483d904996fe386.Components.Pages.Settings
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection"
                     OnSectionChanged="section => activeSection = section" />

    <div class="settings-content">
        @if (isLoading)
        {
            <div class="loading-state">
                <span class="spinner"></span>
                <span>Loading settings…</span>
            </div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@profile" OnSave="SaveProfile" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@notificationPrefs" OnSave="SaveNotifications" />
                    break;
                case "Security":
                    <SecuritySection Security="@securitySettings"
                                     OnChangePassword="HandleChangePassword"
                                     OnRevokeSession="HandleRevokeSession" />
                    break;
                case "Appearance":
                    <AppearanceSection Appearance="@appearanceSettings" OnSave="SaveAppearance" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        isLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notificationsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notificationsTask, securityTask, appearanceTask);

        profile = profileTask.Result;
        notificationPrefs = notificationsTask.Result;
        securitySettings = securityTask.Result;
        appearanceSettings = appearanceTask.Result;
    }

    private async Task SaveProfile(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotifications(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }
}

.settings-dashboard {
    display: grid;
    grid-template-columns: 220px 1fr;
    min-height: calc(100vh - 80px);
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
}

.settings-content {
    padding: 2rem;
    overflow-y: auto;
}

.loading-state {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.75rem;
    padding: 3rem;
    color: #6c757d;
    font-size: 1rem;
}

.spinner {
    width: 20px;
    height: 20px;
    border: 2px solid #dee2e6;
    border-top-color: #0d6efd;
    border-radius: 50%;
    animation: spin 0.6s linear infinite;
}

@@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Shared button styles */
::deep .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s, opacity 0.15s;
}

::deep .btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

::deep .btn-primary {
    background: #0d6efd;
    color: #fff;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

::deep .btn-secondary {
    background: #6c757d;
    color: #fff;
}

::deep .btn-secondary:hover:not(:disabled) {
    background: #5c636a;
}

::deep .btn-danger {
    background: #dc3545;
    color: #fff;
}

::deep .btn-danger:hover:not(:disabled) {
    background: #bb2d3b;
}

